// Local, isolated QA origin only; self-signed certificate is generated by the test.
import https from 'node:https';import fs from 'node:fs';import path from 'node:path';
const root=path.resolve(process.argv[2]);const mime={'.html':'text/html','.js':'text/javascript','.css':'text/css','.json':'application/json','.ttf':'font/ttf','.svg':'image/svg+xml','.webp':'image/webp','.png':'image/png','.webmanifest':'application/manifest+json','.txt':'text/plain'};
const headers={};for(const line of fs.readFileSync(root+'/_headers','utf8').split('\n').slice(1)){if(!line.startsWith('  '))break;const at=line.indexOf(':');if(at>0)headers[line.slice(0,at).trim()]=line.slice(at+1).trim()}
https.createServer({key:fs.readFileSync(process.argv[3]),cert:fs.readFileSync(process.argv[4])},(req,res)=>{const u=new URL(req.url,'https://localhost'),f=path.resolve(root,'.'+decodeURIComponent(u.pathname)),target=u.pathname==='/'?root+'/index.html':f;if(!target.startsWith(root+'/')||!fs.existsSync(target)||!fs.statSync(target).isFile()){res.writeHead(404);res.end();return}res.writeHead(200,{...headers,'content-type':mime[path.extname(target)]||'application/octet-stream','cache-control':'no-store'});fs.createReadStream(target).pipe(res)}).listen(4459,'127.0.0.1',()=>console.log('HTTPS 4459'));
